CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'employee' CHECK (role IN ('admin','employee')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS menus (id BIGSERIAL PRIMARY KEY,menu_date DATE NOT NULL UNIQUE,title VARCHAR(120) NOT NULL,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS menu_options (id BIGSERIAL PRIMARY KEY,menu_id BIGINT NOT NULL REFERENCES menus(id) ON DELETE CASCADE,name VARCHAR(200) NOT NULL,position INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,menu_id BIGINT NOT NULL REFERENCES menus(id) ON DELETE RESTRICT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,menu_id));
CREATE TABLE IF NOT EXISTS order_items (order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,option_id BIGINT NOT NULL REFERENCES menu_options(id) ON DELETE RESTRICT,PRIMARY KEY(order_id,option_id));
CREATE INDEX IF NOT EXISTS idx_menus_date ON menus(menu_date);
CREATE INDEX IF NOT EXISTS idx_orders_menu ON orders(menu_id);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO app_settings(key,value) VALUES('order_mode','today') ON CONFLICT(key) DO NOTHING;

INSERT INTO app_settings(key,value) VALUES('registration_mode','open') ON CONFLICT(key) DO NOTHING;
